  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the final trip price after applying an eligible 20% discount reward.
   * Algorithm:
   * 1. If customer is null or bookingTime is null, return the original price.
   * 2. If customer.membershipPackage is null, return the original price.
   * 3. Check whether the membership package has Award.DISCOUNTS.
   *    - If not, return the original price.
   * 4. Verify that bookingTime is at least 24 hours before the trip's departureTime.
   *    - If not, return the original price.
   * 5. Compute discounted price = price * 0.8.
   * 6. Round or format the result to one decimal place.
   * 7. Return the final amount.
   * Related Features:
   * - price
   * - departureTime
   * - calculateDiscountedPrice(customer, bookingTime)
   * - driver
   * - bookings
   * Related Classes: Customer, MembershipPackage, Award
   * Input:
   * - customer: booking customer.
   * - bookingTime: time of booking as a String, parseable by the system.
   * Output:
   * - double:
   *   - discounted price with one decimal place when conditions are met.
   *   - original trip price otherwise.
   * Pre-condition:
   * - Trip exists.
   * - Trip price is non-negative.
   * - Times are parseable and comparable.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
    {
      return price;
    }

    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return price;
    }

    if (departureTime == null)
    {
      return price;
    }

    try
    {
      DateTimeFormatter formatter = DateTimeFormatter.ISO_DATE_TIME;
      LocalDateTime bookingDateTime = LocalDateTime.parse(bookingTime, formatter);
      LocalDateTime departureDateTime = LocalDateTime.parse(departureTime, formatter);

      if (bookingDateTime.plusHours(24).isAfter(departureDateTime))
      {
        return price;
      }

      double discountedPrice = price * 0.8;
      return Math.round(discountedPrice * 10.0) / 10.0;
    }
    catch (Exception e)
    {
      return price;
    }
    
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the monthly reward points generated by this trip for a given customer.
   * Algorithm:
   * 1. If customer is null or currentMonth is null/empty, return 0.
   * 2. If customer.membershipPackage is null, return 0.
   * 3. Check whether the membership package has Award.POINTS.
   *    - If not, return 0.
   * 4. Iterate over this trip's bookings.
   * 5. For each booking belonging to customer and in currentMonth, add booking.numberOfSeats * 5.
   * 6. Return the accumulated points.
   * Related Features:
   * - bookings
   * - calculateMonthlyPoints(customer, currentMonth)
   * - numberOfSeats
   * Related Classes: Customer, Booking, MembershipPackage, Award
   * Input:
   * - customer: target customer.
   * - currentMonth: month identifier.
   * Output:
   * - int:
   *   - total points earned from this trip in the given month.
   *   - 0 if invalid or unsupported.
   * Pre-condition:
   * - Trip exists.
   * - Customer exists or null is safely handled.
   * - Month format is system-supported.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null || currentMonth.trim().isEmpty())
    {
      return 0;
    }

    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.POINTS))
    {
      return 0;
    }

    int points = 0;
    if (bookings != null)
    {
      for (Booking booking : bookings)
      {
        if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
        {
          points += booking.getNumberOfSeats() * 5;
        }
      }
    }
    return points;
    
  }

