  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Check whether this trip's time window conflicts with a proposed time window.
   * Algorithm:
   * 1. If newDepartureTime or newArrivalTime is null/invalid, return false.
   * 2. Parse this trip's departureTime and arrivalTime.
   * 3. Parse the proposed newDepartureTime and newArrivalTime.
   * 4. If newDepartureTime is not earlier than newArrivalTime, return false.
   * 5. Detect overlap using half-open interval logic:
   *    - conflict exists if the intervals intersect with positive duration.
   *    - boundary-adjacent cases are allowed:
   *      this.end == new.start or new.end == this.start => no conflict.
   * 6. Return true if conflict exists; otherwise false.
   * Related Features:
   * - departureTime
   * - arrivalTime
   * - isTimeConflicting(newDepartureTime, newArrivalTime)
   * Related Classes: None
   * Input:
   * - newDepartureTime: proposed departure time as a String.
   * - newArrivalTime: proposed arrival time as a String.
   * Output:
   * - boolean:
   *   - true if time windows conflict.
   *   - false if they do not conflict or inputs are invalid.
   * Pre-condition:
   * - Existing trip times are present and parseable.
   * - Proposed times are present and parseable.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isTimeConflicting(final String newDepartureTime, final String newArrivalTime)
  {
    if (departureTime == null || arrivalTime == null || newDepartureTime == null || newArrivalTime == null)
    {
      return false;
    }

    try
    {
      DateTimeFormatter formatter = DateTimeFormatter.ISO_DATE_TIME;
      LocalDateTime thisDeparture = LocalDateTime.parse(departureTime, formatter);
      LocalDateTime thisArrival = LocalDateTime.parse(arrivalTime, formatter);
      LocalDateTime proposedDeparture = LocalDateTime.parse(newDepartureTime, formatter);
      LocalDateTime proposedArrival = LocalDateTime.parse(newArrivalTime, formatter);

      if (!proposedDeparture.isBefore(proposedArrival))
      {
        return false;
      }

      return thisDeparture.isBefore(proposedArrival) && proposedDeparture.isBefore(thisArrival);
    }
    catch (Exception e)
    {
      return false;
    }
    
  }

